def _place_team_by_class(con, team_id, classes, level=1):
    """Fill a team's slots with the best hero of each listed class."""
    used = set()
    for slot, cls in enumerate(classes):
        row = _best_of_class(con, cls, used)
        if row:
            used.add(row["id"])
            con.execute(
                "INSERT OR REPLACE INTO team_slots (team_id,slot,hero_id,level,star) "
                "VALUES (?,?,?,?,?)", (team_id, slot, row["id"], level, 1))


def _best_of_class(con, cls, used):
    """Highest-rarity, highest-ATK hero of a class that is not already used."""
    if used:
        marks = ",".join(str(i) for i in used)
        sql = ("SELECT id FROM heroes WHERE cls=? AND id NOT IN (%s) "
               "ORDER BY rarity DESC, base_atk DESC LIMIT 1" % marks)
    else:
        sql = "SELECT id FROM heroes WHERE cls=? ORDER BY rarity DESC, base_atk DESC LIMIT 1"
    return con.execute(sql, (cls,)).fetchone()


