def hero_skills(con, hero_id):
    """A hero's skills, straight from heroSkillLevel + battleSkillRef.

    The JSON columns are parsed into real lists so the GUI can iterate them
    directly instead of parsing strings in the browser.
    """
    out = []
    for r in con.execute("SELECT * FROM hero_skills WHERE hero_id=? ORDER BY id", (hero_id,)):
        row = dict(r)
        for field in ("milestones", "levels", "desc_zh", "desc_en", "lvdesc_zh", "lvdesc_en", "params"):
            val = row.get(field)
            if isinstance(val, str):
                try:
                    row[field] = json.loads(val)
                except (ValueError, TypeError):
                    row[field] = [] if field != "params" else {}
        out.append(row)
    return out

